function aoocRemoveTree(string$root):void{if(!str_starts_with($root,dirname(__DIR__,2).'/.verification-artifacts/aooc-'))throw new TestFailure('SETUP_FAILURE: unsafe cleanup root');if(!is_dir($root))return;$items=scandir($root);if($items===false)throw new TestFailure('SETUP_FAILURE: cleanup read');foreach($items as$item){if($item==='.'||$item==='..')continue;$path=$root.'/'.$item;if(is_dir($path)&&!is_link($path))aoocRemoveTree($path);elseif(!unlink($path))throw new TestFailure('SETUP_FAILURE: cleanup file');}if(!rmdir($root))throw new TestFailure('SETUP_FAILURE: cleanup directory');}
/** @return array{process:resource,pipes:array<int,resource>,request:string} */
function aoocStart(string$config,string$request):array{$spec=[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w'],3=>['pipe','r'],4=>['pipe','r'],5=>['pipe','w'],6=>['pipe','w']];$proc=proc_open([PHP_BINARY,dirname(__DIR__).'/Support/assignment_order_original_worker_runner.php',$config],$spec,$pipes,dirname(__DIR__,2));if(!is_resource($proc))throw new TestFailure('SETUP_FAILURE: worker start');fclose($pipes[0]);fwrite($pipes[3],$request."\n");fclose($pipes[3]);foreach([2,5,6]as$fd)stream_set_blocking($pipes[$fd],false);return['process'=>$proc,'pipes'=>$pipes,'request'=>json_decode($request,true,512,JSON_THROW_ON_ERROR)['requestId']];}
function aoocLine($stream,float$seconds):string{$end=microtime(true)+$seconds;$line='';while(microtime(true)<$end){$read=[$stream];$write=$except=[];$remaining=max(0,$end-microtime(true));$n=stream_select($read,$write,$except,(int)$remaining,(int)(($remaining-(int)$remaining)*1_000_000));if($n===false)throw new TestFailure('SETUP_FAILURE: select');if($n===0)continue;$chunk=fgets($stream);if($chunk===false)continue;$line.=$chunk;if(str_ends_with($line,"\n"))return$line;}throw new TestFailure('SETUP_FAILURE: bounded worker line timeout');}
/** @return array{exit:int,result:string,stderr:string,stdout:string} */
function aoocFinish(array$worker):array{foreach([4]as$fd)if(is_resource($worker['pipes'][$fd]))fclose($worker['pipes'][$fd]);$result=aoocLine($worker['pipes'][6],6);foreach([1,2,5,6]as$fd)stream_set_blocking($worker['pipes'][$fd],true);$stderr=stream_get_contents($worker['pipes'][2]);$stdout=stream_get_contents($worker['pipes'][1]);foreach([1,2,5,6]as$fd)if(is_resource($worker['pipes'][$fd]))fclose($worker['pipes'][$fd]);return['exit'=>proc_close($worker['process']),'result'=>$result,'stderr'=>$stderr,'stdout'=>$stdout];}
/** @return array{exit:int,result:string,stderr:string,stdout:string} */
function aoocFinishFailure(array$worker):array{foreach([1,2,5,6]as$fd)stream_set_blocking($worker['pipes'][$fd],true);$result=stream_get_contents($worker['pipes'][6]);$stderr=stream_get_contents($worker['pipes'][2]);$stdout=stream_get_contents($worker['pipes'][1]);foreach([1,2,4,5,6]as$fd)if(is_resource($worker['pipes'][$fd]))fclose($worker['pipes'][$fd]);return['exit'=>proc_close($worker['process']),'result'=>$result,'stderr'=>$stderr,'stdout'=>$stdout];}
function aoocTerminateAndReap(array$worker):void{foreach($worker['pipes']as$pipe)if(is_resource($pipe))fclose($pipe);if(!is_resource($worker['process']))return;$status=proc_get_status($worker['process']);if($status['running'])proc_terminate($worker['process'],9);proc_close($worker['process']);}
function aoocClosedProcessCleanupSensitivity():void{$process=proc_open([PHP_BINARY,'-r','exit(0);'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2));if(!is_resource($process))throw new TestFailure('SETUP_FAILURE: cleanup sensitivity process');foreach($pipes as$pipe)fclose($pipe);assertSameValue(0,proc_close($process),'Cleanup sensitivity child exits zero.');aoocTerminateAndReap(['process'=>$process,'pipes'=>$pipes]);}
